package org.eclipse.rdf4j.query.algebra.evaluation.rdfparser;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.iteration.QueryExecutionDeadline;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.QueryInterruptedException;
import org.junit.jupiter.api.Test;

class RdfDocumentParserTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String TRIPLE = "<urn:s> <urn:p> <urn:o> .";
	private final RdfDocumentParser parser = new RdfDocumentParser(RdfParseOptions.DEFAULT);

	private Model parse(String text) {
		return parser.parse(VF.createLiteral(text), VF.createLiteral("text/turtle"), null);
	}

	@Test
	void parsesAndDeduplicatesACompleteDocument() {
		Model model = parse(TRIPLE + TRIPLE);
		assertEquals(1, model.size());
		assertThrows(UnsupportedOperationException.class, model::clear);
	}

	@Test
	void malformedSuffixCannotPublishAnApparentlyValidPrefix() {
		assertThrows(QueryEvaluationException.class, () -> parse(TRIPLE + " not Turtle!"));
	}

	@Test
	void emptyDocumentIsAnEmptyGraph() {
		assertTrue(parse("# empty\n").isEmpty());
	}

	@Test
	void preservesBlankNodeIdentityWithinButNotBetweenInvocations() {
		Model first = parse("_:b <urn:p> _:b .");
		Model second = parse("_:b <urn:p> _:b .");
		var statement = first.iterator().next();
		assertEquals(statement.getSubject(), statement.getObject());
		assertNotEquals(statement.getSubject(), second.iterator().next().getSubject());
	}

	@Test
	void preservesLiteralsAndTheirLexicalForms() {
		Model model = parse("<urn:s> <urn:p> \"001\"^^<http://www.w3.org/2001/XMLSchema#integer>; "
				+ "<urn:q> \"colour\"@en-GB .");
		assertTrue(model.contains(VF.createIRI("urn:s"), VF.createIRI("urn:p"),
				VF.createLiteral("001", VF.createIRI("http://www.w3.org/2001/XMLSchema#integer"))));
		assertTrue(model.contains(VF.createIRI("urn:s"), VF.createIRI("urn:q"),
				VF.createLiteral("colour", "en-GB")));
	}

	@Test
	void doesNotInventImplicitPrefixDeclarations() {
		assertThrows(QueryEvaluationException.class, () -> parse("<urn:s> rdf:type <urn:T> ."));
	}

	@Test
	void resolvesAnExplicitBaseWithoutDereferencingIt() {
		Model model = parser.parse(VF.createLiteral("<alice> <name> \"Alice\" ."),
				VF.createLiteral("text/turtle"), VF.createIRI("https://example.org/"));
		assertEquals("https://example.org/alice", model.iterator().next().getSubject().stringValue());
	}

	@Test
	void rejectsMissingAndRelativeBaseForRelativeInput() {
		assertThrows(QueryEvaluationException.class, () -> parse("<alice> <name> \"Alice\" ."));
		assertThrows(QueryEvaluationException.class, () -> parser.parse(VF.createLiteral(TRIPLE),
				VF.createLiteral("text/turtle"), VF.createLiteral("https://example.org/")));
	}

	@Test
	void explicitDocumentBaseOverridesTheExternalBase() {
		Model model = parser.parse(VF.createLiteral("BASE <https://inner.example/>\n<a> <p> <b> ."),
				VF.createLiteral("text/turtle"), VF.createIRI("https://outer.example/"));
		assertEquals("https://inner.example/a", model.iterator().next().getSubject().stringValue());
	}

	@Test
	void rejectsUnsafeOrUnknownFormats() {
		for (String mime : List.of("application/ld+json", "application/rdf+xml", "text/html", "x/unknown")) {
			assertThrows(QueryEvaluationException.class, () -> parser.parse(VF.createLiteral("{}"),
					VF.createLiteral(mime), null));
		}
	}

	@Test
	void rejectsNonStringContentAndLanguageTaggedStrings() {
		assertThrows(QueryEvaluationException.class, () -> parser.parse(VF.createIRI("https://example.org/data.ttl"),
				VF.createLiteral("text/turtle"), null));
		assertThrows(QueryEvaluationException.class, () -> parser.parse(VF.createLiteral(TRIPLE, "en"),
				VF.createLiteral("text/turtle"), null));
	}

	@Test
	void enforcesUtf8BytesNotJavaCharacterCount() {
		String text = "<urn:s> <urn:p> \"å😀\" .";
		long size = text.getBytes(StandardCharsets.UTF_8).length;
		RdfDocumentParser limited = new RdfDocumentParser(new RdfParseOptions(size - 1, 10, 8, 10_000));
		assertThrows(QueryEvaluationException.class, () -> limited.parse(VF.createLiteral(text),
				VF.createLiteral("text/turtle"), null));
	}

	@Test
	void rejectsUnpairedSurrogates() {
		assertThrows(QueryEvaluationException.class,
				() -> parse("<urn:s> <urn:p> \"\uD800\" .".replace("\\uD800", "\uD800")));
	}

	@Test
	void duplicateStatementsStillConsumeTheStatementBudget() {
		RdfDocumentParser limited = new RdfDocumentParser(new RdfParseOptions(1024, 2, 8, 10_000));
		assertThrows(QueryEvaluationException.class, () -> limited.parse(VF.createLiteral(TRIPLE.repeat(3)),
				VF.createLiteral("text/turtle"), null));
	}

	@Test
	void rejectsDeepRecursionBeforeCallingRio() {
		RdfDocumentParser limited = new RdfDocumentParser(new RdfParseOptions(4096, 100, 8, 10_000));
		String text = "<urn:s> <urn:p> " + "[ <urn:p> ".repeat(32) + "<urn:o>" + "]".repeat(32) + " .";
		var failure = assertThrows(QueryEvaluationException.class, () -> limited.parse(VF.createLiteral(text),
				VF.createLiteral("text/turtle"), null));
		assertTrue(failure.getMessage().contains("nesting"));
	}

	@Test
	void bracketsInStringsCommentsAndIrisDoNotCountAsNesting() {
		RdfDocumentParser limited = new RdfDocumentParser(new RdfParseOptions(4096, 100, 2, 10_000));
		String text = "# [[[(((<<<\n<urn:s> <urn:p> \"[[[(((<<<\" .";
		assertEquals(1, limited.parse(VF.createLiteral(text), VF.createLiteral("text/turtle"), null).size());
	}

	@Test
	void preservesNestedTripleTermsWithoutAssertingThem() {
		String text = "VERSION \"1.2\"\n<urn:r> <http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies> "
				+ "<<( <urn:s> <urn:p> <<( <urn:a> <urn:b> <urn:c> )>> )>> .";
		Model model = parse(text);
		assertEquals(1, model.size());
		TripleTerm term = assertInstanceOf(TripleTerm.class, model.iterator().next().getObject());
		assertInstanceOf(TripleTerm.class, term.getObject());
	}

	@Test
	void preservesDefaultAndNamedGraphContexts() {
		Model model = parser.parse(VF.createLiteral(TRIPLE + " <urn:g> { <urn:n> <urn:p> <urn:o> . }"),
				VF.createLiteral("application/trig"), null);
		assertEquals(2, model.size());
		assertTrue(model.contexts().contains(null));
		assertTrue(model.contexts().contains(VF.createIRI("urn:g")));
	}

	@Test
	void refusesReservedGraphMarkersRatherThanConflatingGraphs() {
		for (String graph : List.of(RdfParseVocabulary.DEFAULT_GRAPH.stringValue(), "http://rdf4j.org/schema/rdf4j#nil",
				"http://www.openrdf.org/schema/sesame#nil")) {
			assertThrows(QueryEvaluationException.class, () -> parser.parse(
					VF.createLiteral("<" + graph + "> { " + TRIPLE + " }"), VF.createLiteral("application/trig"),
					null));
		}
	}

	@Test
	void ignoresProcessWideSkolemAndPrefixOverrides() {
		String key = "org.eclipse.rdf4j.rio.skolem_origin";
		String before = System.getProperty(key);
		try {
			System.setProperty(key, "https://unexpected.example/");
			assertTrue(parse("_:b <urn:p> <urn:o> .").iterator().next().getSubject().isBNode());
		} finally {
			if (before == null) {
				System.clearProperty(key);
			} else {
				System.setProperty(key, before);
			}
		}
	}

	@Test
	void preservesTheInterruptFlag() {
		try {
			Thread.currentThread().interrupt();
			assertThrows(QueryEvaluationException.class, () -> parse(TRIPLE));
			assertTrue(Thread.currentThread().isInterrupted());
		} finally {
			Thread.interrupted();
		}
	}

	@Test
	void expiredQueryDeadlineAbortsParsing() throws InterruptedException {
		try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1)) {
			CountDownLatch expired = new CountDownLatch(1);
			try (var registration = deadline.onExpiration(expired::countDown)) {
				assertTrue(expired.await(10, TimeUnit.SECONDS));
			}
			try (var scope = deadline.enter()) {
				assertThrows(QueryInterruptedException.class, () -> parse(TRIPLE));
			}
		}
	}

	@Test
	void supportsConcurrentIndependentDocuments() throws Exception {
		try (var executor = Executors.newFixedThreadPool(4)) {
			Callable<String> job = () -> parse("_:b <urn:p> <urn:o> .").iterator().next().getSubject().stringValue();
			var jobs = java.util.Collections.nCopies(16, job);
			var ids = new HashSet<String>();
			for (var future : executor.invokeAll(jobs)) {
				ids.add(future.get());
			}
			assertEquals(16, ids.size());
		}
	}

	@Test
	void rejectsInvalidLimits() {
		assertThrows(IllegalArgumentException.class, () -> new RdfParseOptions(0, 1, 1, 1));
		assertThrows(IllegalArgumentException.class, () -> new RdfParseOptions(1, 1, 257, 1));
		assertThrows(IllegalArgumentException.class, () -> new RdfParseOptions(1, 1, 1, 3_600_001));
	}
}
